-- name: CreateStockTrade :one
INSERT INTO stock_trade (uuid, stock_trade_time, stock_trade_date, classification, stock_code, stock_id, price, quantity_lot, quantity_share, transaction_fee_percentage, transaction_fee_amount, trade_value, broker_id, investment_manager_id, settlement_date, portfolio_id, trade_type_id, stock_name, broker_name, created_by, updated_by)
VALUES (sqlc.arg('uuid'),
        sqlc.narg('stock_trade_time'),
        sqlc.narg('stock_trade_date'),
        sqlc.narg('classification'),
        (SELECT s.stock_code FROM stock s WHERE s.id = sqlc.narg('stock_id')),
        sqlc.narg('stock_id'),
        sqlc.narg('price'),
        sqlc.narg('quantity_lot'),
        sqlc.narg('quantity_lot')::numeric * 100,
        COALESCE(sqlc.narg('transaction_fee_percentage')::numeric, (SELECT CASE WHEN tt.trade_type_code = 'SELL' THEN b.stock_selling_fee_percentage ELSE b.stock_buying_fee_percentage END FROM broker b, trade_type tt WHERE b.id = sqlc.narg('broker_id') AND tt.id = sqlc.narg('trade_type_id')), 0),
        round(sqlc.narg('price')::numeric * sqlc.narg('quantity_lot')::numeric * 100 * COALESCE(sqlc.narg('transaction_fee_percentage')::numeric, (SELECT CASE WHEN tt.trade_type_code = 'SELL' THEN b.stock_selling_fee_percentage ELSE b.stock_buying_fee_percentage END FROM broker b, trade_type tt WHERE b.id = sqlc.narg('broker_id') AND tt.id = sqlc.narg('trade_type_id')), 0) / 100, 4),
        round(sqlc.narg('price')::numeric * sqlc.narg('quantity_lot')::numeric * 100, 4),
        sqlc.narg('broker_id'),
        sqlc.narg('investment_manager_id'),
        sqlc.narg('settlement_date'),
        sqlc.narg('portfolio_id'),
        sqlc.narg('trade_type_id'),
        (SELECT s.stock_name FROM stock s WHERE s.id = sqlc.narg('stock_id')),
        (SELECT s.broker_name FROM broker s WHERE s.id = sqlc.narg('broker_id')),
        sqlc.arg('actor'),
        sqlc.arg('actor'))
RETURNING uuid;

